package com.alphasystemsrl.alphamenu;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

final class PrintBridgeServer {
    private static final int PORT=17891,VERSION=17;
    private static final String ORIGIN="https://menu.alphasystemsrl.it";
    private final ExecutorService pool=Executors.newCachedThreadPool();
    private final Set<String> printed=new HashSet<>();
    private volatile boolean running;
    private ServerSocket server;
    private final AxonFiscalBridge fiscal;

    PrintBridgeServer(android.content.Context context){fiscal=new AxonFiscalBridge(context.getApplicationContext());}

    void start(){if(running)return;running=true;pool.execute(()->{try{server=new ServerSocket();server.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),PORT));while(running){Socket socket=server.accept();pool.execute(()->handle(socket));}}catch(Exception ignored){if(running)running=false;}});}
    void stop(){running=false;try{if(server!=null)server.close();}catch(Exception ignored){}pool.shutdownNow();}

    private void handle(Socket socket){try(socket){socket.setSoTimeout(125000);InputStream raw=new BufferedInputStream(socket.getInputStream());String requestLine=readLine(raw);if(requestLine==null)return;String[] parts=requestLine.split(" ");if(parts.length<2)return;Map<String,String> headers=new HashMap<>();for(String line;(line=readLine(raw))!=null&&!line.isEmpty();){int split=line.indexOf(':');if(split>0)headers.put(line.substring(0,split).trim().toLowerCase(Locale.ROOT),line.substring(split+1).trim());}String method=parts[0],path=parts[1],origin=headers.getOrDefault("origin","");if(!ORIGIN.equals(origin)){reply(socket,403,new JSONObject().put("message","Origine non consentita."));return;}if("OPTIONS".equals(method)){reply(socket,204,new JSONObject());return;}if("GET".equals(method)&&"/health".equals(path)){reply(socket,200,new JSONObject().put("message","Alpha Menu Android pronto.").put("version",VERSION).put("fiscal",true).put("fiscal_models",new JSONArray().put("Dado RT / RT30")));return;}if(!"POST".equals(method)){reply(socket,404,new JSONObject().put("message","Richiesta non consentita."));return;}int length=Integer.parseInt(headers.getOrDefault("content-length","0"));if(length<1||length>65536)throw new IllegalArgumentException("Dimensione richiesta non valida.");JSONObject data=new JSONObject(new String(readFully(raw,length),StandardCharsets.UTF_8));if(path.startsWith("/fiscal/")){try{reply(socket,200,fiscal.dispatch(path,data));}catch(Exception error){reply(socket,409,new JSONObject().put("message",error.getMessage()==null?"Operazione fiscale non riuscita.":error.getMessage()));}return;}if(!"/print".equals(path)){reply(socket,404,new JSONObject().put("message","Richiesta non consentita."));return;}JSONObject order=data.optJSONObject("order");boolean automatic=data.optBoolean("automatic");String mode=automatic?"auto":data.optString("mode","all");List<Job> jobs=jobs(order,data.optJSONArray("printers"),data.optString("printer_ip"),data.optString("summary_ip"),mode);int count=0;List<String> failures=new ArrayList<>();for(Job job:jobs){String key=job.ip+"|"+job.summary+"|"+order.optString("id")+"|"+order.optString("creato_il");synchronized(printed){if(automatic&&printed.contains(key))continue;}try(Socket printer=new Socket()){printer.connect(new InetSocketAddress(job.ip,9100),4000);printer.setSoTimeout(4000);printer.getOutputStream().write(receipt(order,job.categories,job.summary));printer.getOutputStream().flush();count++;synchronized(printed){if(automatic)printed.add(key);}}catch(Exception error){failures.add(job.ip+": "+error.getMessage());}}if(!failures.isEmpty()){reply(socket,502,new JSONObject().put("message","Stampante non raggiungibile: "+String.join("; ",failures)));return;}reply(socket,200,new JSONObject().put("message",count+" ricevute inviate da Android.").put("printed",count));}catch(Exception error){try{reply(socket,400,new JSONObject().put("message",error.getMessage()==null?"Operazione non riuscita.":error.getMessage()));}catch(Exception ignored){}}}

    private List<Job> jobs(JSONObject order,JSONArray printers,String defaultIp,String summaryIp,String mode)throws Exception{if(order==null||order.optJSONArray("prodotti")==null)throw new IllegalArgumentException("Dati ordine non validi.");if(!"all".equals(mode)&&!"summary".equals(mode)&&!"auto".equals(mode))throw new IllegalArgumentException("Modalità di stampa non valida.");List<Job> result=new ArrayList<>();if("summary".equals(mode)){validateIp(summaryIp);result.add(new Job(summaryIp,null,true));return result;}Set<String> present=new HashSet<>();JSONArray products=order.getJSONArray("prodotti");for(int i=0;i<products.length();i++)present.add(String.valueOf(products.getJSONObject(i).opt("id_categoria")));Map<String,Set<String>> routed=new HashMap<>();if(printers!=null)for(int i=0;i<printers.length();i++){JSONObject printer=printers.getJSONObject(i);String ip=printer.optString("ip");validateIp(ip);String category=String.valueOf(printer.optInt("id_categoria"));if(present.contains(category))routed.computeIfAbsent(ip,k->new HashSet<>()).add(category);}if(!routed.isEmpty())for(Map.Entry<String,Set<String>> item:routed.entrySet())result.add(new Job(item.getKey(),item.getValue(),false));else if(printers==null||printers.length()==0){if(defaultIp!=null&&!defaultIp.isEmpty()){validateIp(defaultIp);result.add(new Job(defaultIp,null,false));}}if("auto".equals(mode)&&summaryIp!=null&&!summaryIp.isEmpty()){validateIp(summaryIp);result.add(new Job(summaryIp,null,true));}return result;}

    private byte[] receipt(JSONObject order,Set<String> categoryIds,boolean summary)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{0x1b,0x40,0x1b,0x74,0x02});PrinterText text=new PrinterText(out);if(summary)text.line("RIEPILOGO",true,true,true);text.line("ORDINE #"+order.optString("numero",order.optString("id")),true,true,true);if("tavolo".equals(order.optString("origine")))text.line("AL TAVOLO",false,false,true);text.line("DATA: "+order.optString("data_richiesta"),false,false,true);text.line("ORA: "+order.optString("ora_richiesta"),false,false,true);text.line("------------------------------------------",false,false,false);for(String[] field:new String[][]{{"nome","Cliente"},{"riferimento","Riferimento"},{"telefono","Telefono"}})if(!order.optString(field[0]).isEmpty())text.line(field[1]+": "+order.optString(field[0]),"nome".equals(field[0]),false,true);text.line("------------------------------------------",false,false,false);JSONArray products=order.getJSONArray("prodotti");for(int i=0;i<products.length();i++){JSONObject product=products.getJSONObject(i);boolean emphasized=!summary&&(categoryIds==null||categoryIds.contains(String.valueOf(product.opt("id_categoria"))));JSONObject config=product.optJSONObject("configurazione"),print=config==null?null:config.optJSONObject("_stampa");if(print!=null&&print.optJSONArray("gusti")!=null){String heading=quantity(product.opt("quantita"))+" x "+print.optString("tipo").toUpperCase(Locale.ITALIAN);if(!print.optString("formato").isEmpty())heading+=" "+print.optString("formato").toUpperCase(Locale.ITALIAN);text.line(heading,emphasized,false,true);JSONArray tastes=print.getJSONArray("gusti");for(int t=0;t<tastes.length()&&t<4;t++){JSONObject taste=tastes.getJSONObject(t);String prefix=taste.optString("quota");text.line("  >> "+(prefix.isEmpty()?"":prefix+" ")+taste.optString("nome").toUpperCase(Locale.ITALIAN),emphasized,false,true);printChanges(text,taste.optJSONArray("senza"),"     -",emphasized);printChanges(text,taste.optJSONArray("aggiunte"),"     +",emphasized);}if(!print.optString("impasto").isEmpty()&&!"classico".equalsIgnoreCase(print.optString("impasto")))text.line("     IMPASTO: "+print.optString("impasto").toUpperCase(Locale.ITALIAN),emphasized,false,true);}else text.line(quantity(product.opt("quantita"))+" x "+product.optString("nome"),emphasized,false,true);}text.line("------------------------------------------",false,false,false);if(!order.optString("note").isEmpty())text.line("NOTE: "+order.optString("note"),false,false,false);if(summary)text.line("TOTALE: EUR "+order.optString("totale"),true,false,true);text.line("\n\n\n",false,false,false);out.write(new byte[]{0x1d,0x56,0x00});return out.toByteArray();}
    private void printChanges(PrinterText text,JSONArray values,String prefix,boolean emphasized)throws Exception{if(values==null)return;for(int i=0;i<values.length()&&i<40;i++)text.line(prefix+values.optString(i).toUpperCase(Locale.ITALIAN),false,false,emphasized);}
    private String quantity(Object value){try{double number=Double.parseDouble(String.valueOf(value));return number==Math.rint(number)?String.valueOf((long)number):String.valueOf(number).replace('.',',');}catch(Exception ignored){return String.valueOf(value);}}
    private void validateIp(String ip)throws Exception{if(ip==null||ip.isEmpty())throw new IllegalArgumentException("Configura la stampante richiesta.");byte[] bytes=InetAddress.getByName(ip).getAddress();if(bytes.length!=4)throw new IllegalArgumentException("IP stampante non valido.");int first=bytes[0]&255,second=bytes[1]&255;if(!(first==10||(first==172&&second>=16&&second<=31)||(first==192&&second==168)))throw new IllegalArgumentException("La stampante deve avere un IP della rete locale.");}
    private byte[] readFully(InputStream input,int length)throws Exception{byte[] body=new byte[length];int offset=0;while(offset<length){int count=input.read(body,offset,length-offset);if(count<0)throw new IllegalArgumentException("Corpo richiesta incompleto.");offset+=count;}return body;}
    private String readLine(InputStream input)throws Exception{ByteArrayOutputStream line=new ByteArrayOutputStream();int value;while((value=input.read())!=-1){if(value=='\n')break;if(value!='\r')line.write(value);if(line.size()>8192)throw new IllegalArgumentException("Richiesta troppo lunga.");}return value==-1&&line.size()==0?null:new String(line.toByteArray(),StandardCharsets.ISO_8859_1);}
    private void reply(Socket socket,int status,JSONObject body)throws Exception{byte[] payload=status==204?new byte[0]:body.toString().getBytes(StandardCharsets.UTF_8);String label=status==200?"OK":status==204?"No Content":status==400?"Bad Request":status==403?"Forbidden":status==404?"Not Found":"Bad Gateway";String headers="HTTP/1.1 "+status+" "+label+"\r\nContent-Type: application/json; charset=utf-8\r\nAccess-Control-Allow-Origin: "+ORIGIN+"\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nAccess-Control-Allow-Private-Network: true\r\nCache-Control: no-store\r\nContent-Length: "+payload.length+"\r\nConnection: close\r\n\r\n";OutputStream output=socket.getOutputStream();output.write(headers.getBytes(StandardCharsets.ISO_8859_1));output.write(payload);output.flush();}
    private static final class Job{final String ip;final Set<String> categories;final boolean summary;Job(String ip,Set<String> categories,boolean summary){this.ip=ip;this.categories=categories;this.summary=summary;}}
    private static final class PrinterText{private final ByteArrayOutputStream out;private final Charset cp850=Charset.forName("CP850");PrinterText(ByteArrayOutputStream out){this.out=out;}void line(String value,boolean large,boolean centered,boolean bold)throws Exception{int width=large?21:42;if(centered)out.write(new byte[]{0x1b,0x61,0x01});String clean=value==null?"":value.replaceAll("[\\p{Cntrl}&&[^\n]]"," ");for(int start=0;start<Math.max(1,clean.length());start+=width){String part=clean.isEmpty()?"":clean.substring(start,Math.min(clean.length(),start+width));out.write(new byte[]{0x1d,0x21,(byte)(large?0x11:0)});out.write(new byte[]{0x1b,0x45,(byte)(bold?1:0)});out.write((part+"\n").getBytes(cp850));if(clean.isEmpty())break;}if(centered)out.write(new byte[]{0x1b,0x61,0x00});}}
}
